namespace FSCM.Domain.Entities;

// Factory-owned identities: never regenerated by a receiving warehouse.
public sealed class FactoryProductionBatch
{
    public Guid Id { get; set; }
    public string Code { get; set; } = "";
    public string FactoryCode { get; set; } = "";
    public string ProductionLine { get; set; } = "";
    public int DailySequence { get; set; }
    public Guid ProductId { get; set; }
    public string Sku { get; set; } = "";
    public string ProductName { get; set; } = "";
    public DateOnly ProductionDate { get; set; }
    public DateOnly ExpirationDate { get; set; }
    public int UnitsPerCarton { get; set; }
    public string OperationKey { get; set; } = "";
    public string RequestHash { get; set; } = "";
    public Guid CreatedByUserId { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
}

public sealed class FactoryPallet
{
    public Guid Id { get; set; }
    public Guid ProductionBatchId { get; set; }
    public string Code { get; set; } = "";
    public string Status { get; set; } = "Packed";
    public Guid? DestinationWarehouseId { get; set; }
    public Guid? ReceiptDocumentId { get; set; }
    public DateTimeOffset? DispatchedAt { get; set; }
    public DateTimeOffset? ReceivedAt { get; set; }
    public string? ReceiptInspectionJson { get; set; }
    public int Version { get; set; } = 1;
}

public sealed class FactoryCarton
{
    public Guid Id { get; set; }
    public Guid PalletId { get; set; }
    public string Code { get; set; } = "";
    public int Sequence { get; set; }
}

public sealed class FactoryProductUnit
{
    public Guid Id { get; set; }
    public Guid CartonId { get; set; }
    public string Code { get; set; } = "";
    public int Sequence { get; set; }
}

// WMS-owned acknowledgement outbox; receipt and stock commit in the WMS transaction.
public sealed class FactoryReceiptSync
{
    public Guid PalletId { get; set; }
    public Guid ReceiptDocumentId { get; set; }
    public Guid WarehouseId { get; set; }
    public DateTimeOffset ReceivedAt { get; set; }
    public DateTimeOffset? SyncedAt { get; set; }
    public int Attempts { get; set; }
    public string? LastError { get; set; }
    public string? ReceiptInspectionJson { get; set; }
}
